public class PerceptronUpdaterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("predict fires above the threshold", 1,
                    PerceptronUpdater.predict(new double[]{1, 1}, -1.5, new double[]{1, 1}));
            check("predict stays quiet below the threshold", 0,
                    PerceptronUpdater.predict(new double[]{1, 1}, -1.5, new double[]{1, 0}));
            check("a sum of exactly 0 does not fire", 0,
                    PerceptronUpdater.predict(new double[]{1, 1}, -2.0, new double[]{1, 1}));

            check("update from zero weights toward target 1", "[0.5, 1.0, 0.5]",
                    java.util.Arrays.toString(PerceptronUpdater.update(
                            new double[]{0, 0}, 0.0, new double[]{1, 2}, 1, 0.5)));
            check("a correct prediction changes nothing", "[0.5, 1.0, 0.5]",
                    java.util.Arrays.toString(PerceptronUpdater.update(
                            new double[]{0.5, 1.0}, 0.5, new double[]{1, 2}, 1, 0.5)));
            check("a false positive pulls the weights down", "[1.75, 1.75, 0.75]",
                    java.util.Arrays.toString(PerceptronUpdater.update(
                            new double[]{2, 2}, 1.0, new double[]{1, 1}, 0, 0.25)));
            check("a negative input moves its weight the other way", "[0.5, -0.25, 0.25]",
                    java.util.Arrays.toString(PerceptronUpdater.update(
                            new double[]{0, 0}, 0.0, new double[]{2, -1}, 1, 0.25)));

            double[] weights = {0, 0};
            PerceptronUpdater.update(weights, 0.0, new double[]{1, 2}, 1, 0.5);
            check("the weight array passed in is not modified", "[0.0, 0.0]",
                    java.util.Arrays.toString(weights));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

