/**
 * A single perceptron: a thresholded weighted sum plus one learning step.
 */
public class PerceptronUpdater {

    public static int predict(double[] weights, double bias, double[] inputs) {
        double sum = bias;
        for (int i = 0; i < weights.length; i++) {
            sum += weights[i] * inputs[i];
        }
        return sum > 0 ? 1 : 0;
    }

    public static double[] update(double[] weights, double bias, double[] inputs,
                                  int target, double learningRate) {
        int error = target - predict(weights, bias, inputs);
        double[] updated = new double[weights.length + 1];
        for (int i = 0; i < weights.length; i++) {
            updated[i] = weights[i] + learningRate * error * inputs[i];
        }
        updated[weights.length] = bias + learningRate * error;
        return updated;
    }
}
